                    "sql": "create or replace table ANDAMEN_DB.MAPLEMONK.ANDAMEN_DB_FM_LM_dashboard as select a.order_id ,a.awb ,a.marketplace Final_Marketplace ,a.reference_code ,a.marketplace marketplace ,a.source_pincode ,a.pincode ,warehouse warehouse_name ,b.Same_Day_Cut_Off ,case WHEN (EXTRACT(HOUR FROM order_timestamp)) >= b.Same_Day_Cut_Off THEN DATEADD(DAY, 1, order_timestamp) ::date ELSE order_timestamp::date END AS Target_dispatch_Pre ,case when upper(dayname(Target_dispatch_Pre)) = \'SUN\' then DATEADD(DAY, 1, Target_dispatch_Pre) else Target_dispatch_Pre END as Target_dispatch ,a.order_timestamp as order_date ,CASE WHEN TO_TIME(order_timestamp) < \'17:00:00\' THEN order_timestamp::date ELSE DATEADD(DAY, 1, order_timestamp)::date END AS adjusted_order_date ,CASE WHEN TO_TIME(order_timestamp) < \'14:00:00\' THEN order_timestamp::date ELSE DATEADD(DAY, 1, order_timestamp)::date END AS ops_order_date ,coalesce(cf.pickup_date,a.dispatch_date) as Order_Manifest_date ,a.qc_pass_date as qc_confirmed_at ,shipping_last_update_date as Order_Shipping_Last_Update_Date ,coalesce(delivery_date,delivered_date) as order_delivered_date ,upper(shipping_status) shipping_status ,upper(order_status) order_status ,a.COURIER ,Source ,payment_mode ,cf.courier_partner as courier_partner_Clickpost ,upper(case when lower(a.marketplace) like \'%flipkart%\' then \'ekart\' when lower(source) like any (\'%gofynd%\', \'%amazon smart%\') then \'amazon flex\' when lower(a.marketplace) like \'%myntra%\' or lower(a.courier) like any (\'myntrappmpcourier\',\'myntra\') then \'myntra\' else \'Self Ship\' end) as courier_partner ,upper(case when (lower(order_status) like \'%cancel%\' or lower(oms_order_status) like \'%cancel%\') then \'CANCELLED\' else coalesce((case when lower(CURRENT_STATUS) like \'deliver%\' then \'DELIVERED\'else null end) ,FINAL_SHIPPING_STATUS,shipping_status,order_status) end) final_status ,case when upper(final_status) in (\'DELIVERED\') then 1 else 0 end as delivered_