21 - 144 hours\' when Time_from_Order <= 144 then \'7. 145 - 168 hours\' else \'8. More than a week\' end as Time_From_Order_Category ,datediff(\'hour\',order_timestamp::timestamp ,order_manifest_date::timestamp) Dispatch_Speed ,datediff(\'hour\',order_timestamp::timestamp ,order_delivered_date::timestamp) o2d_delivery_Speed ,datediff(\'hour\',order_manifest_date::timestamp ,order_delivered_date::timestamp) s2d_delivery_Speed ,upper(case when Dispatch_Speed < 2 then \'0- 2 hours\' when Dispatch_Speed < 6 then \'2 - 6 hours\' when Dispatch_Speed < 12 then \'6 - 12 hours\' when Dispatch_Speed < 24 then \'12 - 24 hours\' when Dispatch_Speed < 48 then \'24-48 hours\' when Dispatch_Speed < 72 then \'48-72 hours\' when Dispatch_Speed < 96 then \'72-96 hours\' when order_manifest_date is not NULL then \'> 96 hours\' when order_manifest_date is NULL then \'Not Dispatched\' end) as Dispatch_Speed_flag ,greatest(case when hour(order_timestamp::timestamp) < hour(try_cast(same_day_cut_off as time)) then datediff(\'day\',order_timestamp::timestamp ,coalesce(order_manifest_date::timestamp,convert_timezone(\'America/Los_Angeles\', \'Asia/Kolkata\', current_timestamp())::timestamp )) else datediff(\'day\',order_timestamp::timestamp ,coalesce(order_manifest_date::timestamp,convert_timezone(\'America/Los_Angeles\', \'Asia/Kolkata\', current_timestamp())::timestamp )) -1 end,0) as Dispatch_Flag ,Case when Dispatch_Flag=0 then \'Same Day\' when Dispatch_Flag=1 then \'Next Day\' else \'2+ Days\' end as Final_Dispatch_Bucket ,case when delivered_order = 1 then datediff(\'hour\',order_manifest_date::timestamp , order_delivered_date ) end as Delivery_Speed ,case when delivered_order = 1 then datediff(\'hour\',order_manifest_date::timestamp ,order_delivered_date ) else datediff(\'hour\',order_manifest_date::timestamp ,convert_timezone(\'America/Los_Angeles\', \'Asia/Kolkata\', current_timestamp())::timestamp) end as deliver_time ,upper(case when delivered_order = 1 and datediff(\'hour\',order_manifest_date::timestamp,order_delivered_date ) < 24 then \'< 24 hours\' when delivered_order = 1 and datediff(\'hour\',order_manifest_date::timestamp,order_delivered_date ) < 48 then \'24-48 hours\' when delivered_order = 1 and datediff(\'hour\',order_manifest_date::timestamp,order_delivered_date ) < 72 then \'48-72 hours\' when delivered_order = 1 and datediff(\'hour\',order_manifest_date::timestamp,order_delivered_date ) < 96 then \'72-96 hours\' when delivered_order = 1 then \'> 96 hours\' else \'Not Delivered\' end) as delivery_time_flag ,upper(case when delivered_order = 1 and datediff(\'hour\',ops_order_date::timestamp,order_delivered_date ) < 24 then \'< 24 hours\' when delivered_order = 1 and datediff(\'hour\',ops_order_date::timestamp,order_delivered_date ) < 48 then \'24-48 hours\' when delivered_order = 1 and datediff(\'hour\',ops_order_date::timestamp,order_delivered_date ) < 72 then \'48-72 hours\' when delivered_order = 1 and datediff(\'hour\',ops_order_date::timestamp,order_delivered_date ) < 96 then \'72-96 hours\' when delivered_order = 1 then \'> 96 hours\' else \'Not Delivered\' end) as delivery_time_flag_o2d ,upper(case when delivered_order = 1 and datediff(\'hour\',ops_order_date::timestamp,order_delivered_date ) < 24 then \'< 1 day \' when delivered_order = 1 and datediff(\'hour\',ops_order_date::timestamp,order_delivered_date ) < 48 then \'1-2 Days\' when delivered_order = 1 and datediff(\'hour\',ops_order_date::timestamp,order_delivered_date ) < 72 then \'2-3 Days\' when delivered_order = 1 and datediff(\'hour\',ops_order_date::timestamp,order_delivered_date ) < 96 then \'3-4 Days\' when delivered_order = 1 then \'> 4 Days\' else \'Not Delivered\' end) as delivery_Day_flag_o2d ,upper(case when lower(final_status) like \'%cancel%\' then \'CANCELLED\' when not(lower(final_status) like \'%cancel%\') and lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\') and not(final_status in (\'RTO\',\'IN TRANSIT\' ,\'LOST\',\'DELIVERED\')) then upper(\'amazon fulfilled - not dispatched\') when not(lower(final_status) like \'%cancel%\') and lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\') and (final_status in (\'RTO\',\'IN TRANSIT\' ,\'LOST\',\'DELIVERED\')) then upper(\'amazon fulfilled - dispatched\') when not(lower(final_status) like \'%cancel%\') and not (lower(a.source_pincode) like \'%amazon%\') and not(final_status in (\'RTO\',\'IN TRANSIT\' ,\'LOST\',\'DELIVERED\')) then \'NOT DISPATCHED\' when (final_status in (\'RTO\',\'IN TRANSIT\' ,\'LOST\',\'DELIVERED\')) then \'DISPATCHED\' when not(final_status in (\'RTO\',\'IN TRANSIT\' ,\'LOST\',\'DELIVERED\')) then \'NOT DISPATCHED\' end) as dispatch_status ,coalesce(tat.s2d_tat, 2) as TARGET_TAT ,case when not(lower(final_status) like \'%cancel%\') then datediff(\'hour\',order_manifest_date::timestamp,DATEADD(DAY, 1, DATE_TRUNC(DAY,DATEADD(DAY, coalesce(tat.s2d_tat, 2), order_manifest_date::timestamp)))) end target_tat_hours ,case when not(lower(final_status) like \'%cancel%\') then datediff(\'hour\',order_manifest_date::timestamp,ifnull(order_delivered_date, convert_timezone(\'America/Los_Angeles\', \'Asia/Kolkata\', current_timestamp())::timestamp)) end DELIVERY_TAT ,case when DELIVERY_TAT <= target_tat_hours then \'ON TIME\' when DELIVERY_TAT > target_tat_hours then \'DELAYED\' end TAT_PERFORMANCE ,upper (case when (not(lower(final_status) like \'%cancel%\')) AND lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\') and order_delivered_date is null then \'amazon fulfilled\' when (not(lower(final_status) like \'%cancel%\')) AND lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\') and order_delivered_date is not null then \'amazon fulfilled - delivered\' when (not(lower(final_status) like \'%cancel%\')) and order_delivered_date is null and DELIVERY_TAT <= target_tat_hours then \'In Transit - On Time\' when (not(lower(final_status) like \'%cancel%\')) and order_delivered_date is null and DELIVERY_TAT > target_tat_hours then \'In Transit - Delayed\' when (not(lower(final_status) like \'%cancel%\')) and order_delivered_date is not null and DELIVERY_TAT > target_tat_hours then \'delivered - Delayed\' when (not(lower(final_status) like \'%cancel%\')) and order_delivered_date is not null and DELIVERY_TAT <= target_tat_hours then \'delivered - On Time\' else \'zone not mapped\' end) as s2d_status ,case when not(lower(final_status) like \'%cancel%\') then datediff(\'hour\',ops_order_date::timestamp,DATEADD(DAY, 1, DATE_TRUNC(DAY,DATEADD(DAY, coalesce(tat.o2d_tat, 4) ,ops_order_date::timestamp)))) end target_tat_hours_o2d ,case when not(lower(final_status) like \'%cancel%\') then datediff(\'hour\',ops_order_date::timestamp,ifnull(order_delivered_date, convert_timezone(\'America/Los_Angeles\', \'Asia/Kolkata\', current_timestamp())::timestamp)) end DELIVERY_TAT_o2d ,upper (case when (not(lower(final_status) like \'%cancel%\')) AND lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\') and order_delivered_date is null then \'amazon fulfilled\' when (not(lower(final_status) like \'%cancel%\')) AND lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\') and order_delivered_date is not null then \'amazon fulfilled - delivered\' when (not(lower(final_status) like \'%cancel%\') and order_manifest_date is null) then \'Not dispatched\' when (not(lower(final_status) like \'%cancel%\') and order_delivered_date is null and DELIVERY_TAT_o2d <= target_tat_hours_o2d ) then \'In Transit On Time\' when (not(lower(final_status) like \'%cancel%\') and order_delivered_date is null and DELIVERY_TAT_o2d > target_tat_hours_o2d ) then \'In Transit Delayed\' when (not(lower(final_status) like \'%cancel%\') and order_delivered_date is not null and DELIVERY_TAT_o2d > target_tat_hours_o2d) then \'delivered Delayed\' when (not(lower(final_status) like \'%cancel%\') and order_delivered_date is not null and DELIVERY_TAT_o2d <= target_tat_hours_o2d ) then \'delivered On Time\' else \'zone not mapped\' end) as o2d_status ,case when (not(lower(final_status) like \'%cancel%\')) then datediff(\'hour\',order_timestamp::timestamp,ifnull(order_manifest_date, convert_timezone(\'America/Los_Angeles\', \'Asia/Kolkata\', current_timestamp())::timestamp)) end DELIVERY_TAT_o2s ,upper(CASE WHEN ((NOT (LOWER(final_status) LIKE \'%cancel%\')) AND lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\')) and order_manifest_date is null THEN upper(\'amazon-fulfilled\') WHEN ((NOT (LOWER(final_status) LIKE \'%cancel%\')) AND lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\') and order_manifest_date is not null) then upper(\'amazon-dispatched\') WHEN ( (NOT (LOWER(final_status) LIKE \'%cancel%\')) AND upper(dispatch_status) = \'NOT DISPATCHED\' and CONVERT_TIMEZONE(\'America/Los_Angeles\', \'Asia/Kolkata\', CURRENT_TIMESTAMP())::TIMESTAMP::date <= Target_dispatch )THEN \'Not Dispatched On Time\' WHEN ( (NOT (LOWER(final_status) LIKE \'%cancel%\')) AND upper(dispatch_status) = \'NOT DISPATCHED\' and CONVERT_TIMEZONE(\'America/Los_Angeles\', \'Asia/Kolkata\', CURRENT_TIMESTAMP())::TIMESTAMP::date > Target_dispatch ) THEN \'Not Dispatched Delayed\' WHEN ( (NOT (LOWER(final_status) LIKE \'%cancel%\')) AND order_manifest_date IS NOT NULL and upper(dispatch_status) = \'DISPATCHED\' AND order_manifest_date::date > Target_dispatch ) THEN \'Dispatched Delayed\' WHEN ( (NOT (LOWER(final_status) LIKE \'%cancel%\')) AND order_manifest_date IS NOT NULL and upper(dispatch_status) = \'DISPATCHED\' AND order_manifest_date::date <= Target_dispatch ) THEN \'Dispatched On Time\' END) AS o2s_status, coalesce(tat.s2d_tat, 2) as s2d_sla, coalesce(tat.o2d_tat, 4) - coalesce(tat.s2d_tat, 2) as o2s_sla, coalesce(tat.o2d_tat, 4) as o2d_sla, upper(case when lower(final_status) like \'%cancel%\' then \'CANCELLED\' when not(lower(final_status) like \'%cancel%\') and lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\') and order_delivered_date is NULL then upper(\'amazon fulfilled\') when not(lower(final_status) like \'%cancel%\') and lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\') and order_delivered_date is not NULL then upper(\'amazon delivered\') when not(lower(final_status) like \'%cancel%\') and not lower(a.source) like any (\'%gofynd%\', \'%amazon smart%\') and order_delivered_date is NULL then \'NOT DELIVERED\' else \'DELIVERED\' end) as delivery_status ,dateadd(day, coalesce(tat.o2d_tat, 4), order_timestamp::timestamp) as promised_delivery_date ,TAT.zone , CASE WHEN datediff(\'day\',order_timestamp::timestamp ,current_timestamp)=0 THEN \'0 Days\' WHEN datediff(\'day\',order_timestamp::timestamp ,current_timestamp)=1 THEN \'1 Days\' WHEN datediff(\'day\',order_timestamp::timestamp ,current_timestamp)=2 THEN \'2 Days\' WHEN datediff(\'day\',order_timestamp::timestamp ,current_timestamp)=3 THEN \'3 Days\' WHEN datediff(\'day\',order_timestamp::timestamp ,current_timestamp)=4 THEN \'4 Days\' WHEN datediff(\'day\',order_timestamp::timestamp ,current_timestamp)=5 THEN \'5 Days\' WHEN datediff(\'day\',order_timestamp::timestamp ,current_timestamp)>5 THEN \'More than 5 days\' END AS Aging_in_Days, CASE WHEN lower(a.PRODUCT_CATEGORY) IN (\'bed\',\'mattress\',\'matresses\',\'recliner\') THEN \'Heavy\' WHEN lower(a.PRODUCT_SUB_CATEGORY) IN (\'memory foam mattress topper\',\'microfiber mattress topper\',\'mattress topper\') THEN \'Heavy\' ELSE \'Light\' END AS Product_Weight ,PRODUCT_CATEGORY ,CITY ,STATE ,CASE WHEN lower(cf.courier_partner) like \'%reverse%\' then \'Reverse\' ELSE \'Forward\' END AS Shipment_Flow from (select * from ANDAMEN_DB.MAPLEMONK.ANDAMEN_DB_sales_consolidated) a left join ANDAMEN_DB.MAPLEMONK.ANDAMEN_DB_CLICKPOST_FACT_ITEMS cf on lower(cf.awb) = lower(a.awb) left join ANDAMEN_DB.MAPLEMONK.MARKETPLACE_FULFILLMENT_CUTOFF b on lower(b.marketplace) = lower(a.marketplace) left join ANDAMEN_DB.MAPLEMONK.AMAZON_S3_PINCODE_ZONE_MAPPING pz on lower(pz.\"Delivery Pincode\") = lower(a.pincode) left join (select zone, case when zone = \'z_a\' then 2 when zone = \'z_b\' then 3 when zone = \'z_c\' then 4 when zone = \'z_d\' then 6 when zone = \'z_e\' then 8 else 2 end as s2d_tat, case when zone = \'z_a\' then 4 when zone = \'z_b\' then 5 when zone = \'z_c\' then 6 when zone = \'z_d\' then 8 when zone = \'z_e\' then 10 else 4 end as o2d_tat from (select distinct lower(zone) as zone from ANDAMEN_DB.MAPLEMONK.AMAZON_S3_PINCODE_ZONE_MAPPING) ) TAT on lower(tat.zone) = lower(coalesce(pz.zone, \'z_a\')) group by a.order_id ,Final_Marketplace ,a.PRODUCT_CATEGORY ,a.PRODUCT_SUB_CATEGORY ,a.reference_code ,a.marketplace ,a.source_pincode ,a.pincode ,warehouse_name ,a.order_timestamp ,b.same_day_cut_off ,Order_Shipping_Last_Update_Date ,case when upper(coalesce(final_shipping_status,shipping_status,order_status)) in (\'DELIVERED\') then a.shipping_last_update_date end ,shipping_status ,order_status ,upper(case when (lower(order_status) like \'%cancel%\' or lower(oms_order_status) like \'%cancel%\') then \'CANCELLED\' else coalesce((case when lower(CURRENT_STATUS) like \'deliver%\' then \'DELIVERED\'else null end) ,FINAL_SHIPPING_STATUS,shipping_status,order_status) end) ,a.COURIER ,cf.courier_partner ,Source ,payment_mode ,tat.zone ,tat.s2d_tat ,tat.o2d_tat ,a.awb, coalesce(cf.pickup_date,a.dispatch_date), order_delivered_date ,PRODUCT_CATEGORY ,CITY ,STATE ;",
